package max;

public class WhileLooping {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Whileloop();
		System.out.println("============");
		int count=1;
		while(count<=5)
		{
			System.out.println(count);
			count++;
		}
	}
	public static void Whileloop()
	{
		int value=1;
		while(value<=4)
		{
			System.out.println("*");
			value++;
		}
	}

}
